    r"company|products|product|documents|document|courses|course|schools|school|"
    r"universities|university|professors|professor|instructors|instructor|members|member|"
    r"users|user|players|player|teams|team|cars|car|airlines|airline|airports|airport|"
    r"flights|flight|hotels|hotel|rooms|room|buildings|building|stations|station|"
    r"artists|artist|songs|song|albums|album|movies|movie|films|film|actors|actor|"
    r"directors|director|books|book|authors|author|papers|paper|projects|project|"
    r"jobs|job|orders|order|stores|store|branches|branch|managers|manager|drivers|"
    r"driver|owners|owner|dogs|dog|cats|cat|pets|pet|states|state|regions|region|"
    r"continents|continent|languages|language|programs|program|degrees|degree|"
    r"channels|channel|series|cartoons|cartoon|episodes|episode|games|game|matches|"
    r"match|tournaments|tournament|colleges|college|enrolments|enrollments|"
    r"addresses|address|locations|location|facilities|facility|services|service|"
    r"accounts|account|transactions|transaction|payments|payment|invoices|invoice|"
    r"shipments|shipment|suppliers|supplier|parts|part|devices|device|phones|phone|"
    r"computers|computer|laptops|laptop|cameras|camera|battles|battle|ships|ship|"
    r"mountains|mountain|rivers|river|lakes|lake|parks|park|bridges|bridge|"
    r"churches|church|architects|architect|musicians|musician|bands|band|"
    r"instruments|instrument|performers|performer|singers|singer|writers|writer|"
    r"editors|editor|publishers|publisher|journalists|journalist|reporters|reporter|"
    r"guests|guest|hosts|host|visitors|visitor|tourists|tourist|passengers|passenger|"
    r"pilots|pilot|engineers|engineer|scientists|scientist|researchers|researcher|"
    r"doctors|doctor|nurses|nurse|patients|patient|medications|medication|drugs|drug|"
    r"treatments|treatment|diagnoses|diagnosis|symptoms|symptom|allergies|allergy|"
    r"vaccines|vaccine|appointments|appointment|schedules|schedule|events|event|"
