def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    return (text or "").strip().rstrip(";").strip()


def _table_columns(schema):
    """Best-effort {table: [columns]} parsed from CREATE statements."""
    out = {}
    for m in CREATE_TBL.finditer(schema or ""):
        name, body = m.group(1), m.group(2)
        cols = []
        depth = 0
        line = ""
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                if depth == 0:
                    break
                depth -= 1
            if ch == "," and depth == 0:
                cm = COL_LINE.match(line)
                if cm and cm.group(1).lower() not in CONSTRAINT_KW:
                    cols.append(cm.group(1))
                line = ""
            else:
                line += ch
        cm = COL_LINE.match(line)
        if cm and cm.group(1).lower() not in CONSTRAINT_KW:
            cols.append(cm.group(1))
        out[name] = cols
    return out


def _referenced_tables(sql, tables):
    ref = [t for t in tables if re.search(r"\b" + re.escape(t) + r"\b", sql or "", re.I)]
    return ref or list(tables)


def _schema_facts(sql, tables, ref):
    """Show the REAL columns of every table the draft touches (kills invented ids)."""
    lines = []
    for t in ref[:8]:
        lines.append("%s(%s)" % (t, ", ".join(tables[t])))
    if not lines:
        return ""
    return "Actual columns of the tables your query references:\n" + "\n".join(lines)


def _probe_values(env, sql, schema):
    """For string literals used in the draft, show what is actually stored."""
    lits = [l.replace("''", "'") for l in LITERAL.findall(sql)]
    lits = [l for l in lits if l and l.upper() not in ("T", "F", "Y", "N")]
    if not lits:
        return ""
    tables = _table_columns(schema)
    ref = _referenced_tables(sql, tables)
    text_cols = []
    for t in ref:
        for c in tables[t]:
            if re.search(r"name|text|title|type|summary|detail|description|code|language|status|country|city|program|degree|channel|series", c, re.I):
                text_cols.append((t, c))
    lines = []
    seen = set()
    for lit in lits[:3]:
        core = re.sub(r"[%_]", "", lit).strip()
        words = [w for w in re.split(r"\s+", core) if len(w) >= 3]
        probe = words[0] if words else core
        if not probe:
            continue
        for t, c in text_cols[:14]:
            key = (t, c, probe.lower())
            if key in seen:
                continue
            seen.add(key)
            q = (
                "SELECT DISTINCT \"%s\" FROM \"%s\" WHERE \"%s\" LIKE '%%%s%%' LIMIT 6"
                % (c, t, c, probe.replace("'", "''"))
            )
            try:
                r = env.execute(q, max_rows=6)
            except Exception:
                continue
            if r.get("ok") and r.get("rows"):
                vals = [row[0] for row in r["rows"]]
                lines.append("%s.%s contains values like %r (your filter used %r)" % (t, c, vals, lit))
            if len(lines) >= 8:
                break
        if len(lines) >= 8:
            break
    return "\n".join(lines)


def _duplicate_info(res):
    """Detect repeated identical result rows (join fan-out / missing DISTINCT)."""
    rows = res.get("rows") or []
    if len(rows) < 2:
        return None
    try:
        keys = [tuple(r) for r in rows]
        uniq = set(keys)
    except TypeError:
        return None
    if len(uniq) == len(keys):
        return None
    counts = {}
    for k in keys:
        counts[k] = counts.get(k, 0) + 1
    dups = [(k, n) for k, n in counts.items() if n > 1][:4]
    shown = "; ".join("%r x%d" % (list(k), n) for k, n in dups)
    return (
        "The result contains REPEATED IDENTICAL ROWS: %d rows returned but only %d distinct rows. "
        "Examples of duplication: %s. This is usually join fan-out: one entity matches several rows "
        "in a joined table." % (len(keys), len(uniq), shown)
    )


GUIDANCE = (
    "Checklist while repairing:\n"
    "- Only reference tables/columns listed in the schema above; verify exact spelling against the "
    "actual column lists provided. Relationship/link tables often use unexpected id column names.\n"
    "- String comparisons in SQLite are case-sensitive by default and stored values may differ "
    "from the question's wording (singular/plural, abbreviations, extra spaces, casing). Prefer "
    "matching the ACTUAL stored values shown below, or use LIKE / LOWER(...) to be tolerant.\n"
    "- If identical rows repeat in the result, the expected answer almost always wants each entity "
    "ONCE: add SELECT DISTINCT (or group appropriately). Keep duplicates only if the question "
    "explicitly asks per-occurrence/per-enrolment records.\n"
    "- For anti-joins ('does not have any ...'), check EVERY id column of the relationship table "
    "that could record the link (e.g. both endpoints of a symmetric relation), using the real "
    "column names shown above.\n"
    "- Select exactly the columns the question asks for. If the question asks which WHOLE entities "
    "qualify ('which countries...', 'which students...', 'show the details...') rather than a "
    "specific attribute, the expected output is usually ALL columns of that entity's table "
    "(SELECT T1.*), not just a name. If it names specific attributes, select only those.\n"
    "- Apply hint formulas literally; watch NULLs, ties with LIMIT, and DISTINCT only when needed."
)


def solve(task, env):
    schema = env.schema(task["db_id"])
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        pass
    if desc:
        user += f"\n\nColumn descriptions:\n{desc[:3000]}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)
    if not sql:
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=20)
    except Exception:
        res = {"ok": True, "n_rows": 1}

    tables = _table_columns(schema)
    ref = _referenced_tables(sql, tables)

    problems = []
    if not res.get("ok"):
        problems.append("It FAILED with error: %s" % res.get("error", "unknown"))
    elif res.get("n_rows", 0) == 0:
        problems.append(
            "It executed but returned 0 rows. That usually means a filter value does not match "
            "what is stored, a join condition is wrong, or a referenced column is wrong "
            "(e.g. an anti-join subquery selecting a nonexistent/mismatched id column)."
        )
    else:
        dup = _duplicate_info(res)
        if dup:
            problems.append(dup)
        # Entity-style question answered with a narrow projection: likely wants full rows.
        ncols = len(res.get("columns") or [])
        if ncols and ENTITY_Q.search(task.get("question") or ""):
            wide = [t for t in ref if len(tables.get(t, [])) >= max(4, ncols + 2)]
            if wide and not re.search(r"select\s+(?:distinct\s+)?[\w.\"`]+\.\*", sql, re.I):
                t = wide[0]
                problems.append(
                    "The question asks WHICH entities qualify, but your query returns only %d "
                    "column(s). For such questions the expected answer is usually ALL columns of "
                    "the entity's table: %s has columns (%s). Consider SELECT T1.* (keep DISTINCT "
                    "only if it does not change which entities appear)." % (ncols, t, ", ".join(tables[t]))
                )

    if not problems:
        return {"sql": sql}

    feedback = ["Your draft query was:", "```sql\n" + sql + "\n```"]
    feedback.extend(problems)
    facts = _schema_facts(sql, tables, ref)
    if facts:
        feedback.append(facts)
    probes = _probe_values(env, sql, schema)
    if probes:
        feedback.append("Actual stored values found by probing the database:\n" + probes)
    feedback.append(GUIDANCE)
    feedback.append(
        "Write a corrected query that answers the original question. Keep any parts of the draft "
        "that were right. Return ONLY the final query in a single ```sql code block."
    )

    messages.append({"role": "assistant", "content": reply})
    messages.append({"role": "user", "content": "\n\n".join(feedback)})
    try:
        reply2 = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=20)
    except Exception:
        res2 = {"ok": False}
    # Prefer the repaired query if it runs; if it errors, fall back to the draft.
    if res2.get("ok") or not res.get("ok"):
        return {"sql": sql2}
    return {"sql": sql}

proposal.raw:
**Diagnosis.** All four failures are *silent* errors: the draft executes fine, so the incumbent never spends its second call. Two distinct silent patterns dominate: (a) join fan-out duplicates without DISTINCT (sp0536 8 vs 5 rows, sp0600 2 vs 1 row), and (b) wrong projection width for "which entities…" questions (sp0755 wants all columns). The third pattern is a broken anti-join returning 0 rows where the repair call had no grounded facts about the relationship table (sp0894 invented `student_id`).

Prior rounds tried duplicate-triggered repair with generic guidance and gained nothing — the missing ingredient is **grounding**: probe the actual columns of the tables the query references (so invented id columns get corrected deterministically) and show the exact duplicated rows, then give a concrete decision rule ("repeated identical rows ⇒ add DISTINCT unless the question asks per-occurrence"). I also extend the trigger to entity-style questions whose projection is narrower than the entity table, with feedback that shows the real column list. One coherent edit: make the existing repair loop fire on silent failures, backed by schema/value probes.

